const slider=document.getElementById('cutoff');
function render(){const row=thresholdData[Number(slider.value)];document.getElementById('cutoffValue').textContent=row.threshold.toFixed(4);document.getElementById('sens').textContent=(row.sensitivity*100).toFixed(1)+'%';document.getElementById('spec').textContent=(row.specificity*100).toFixed(1)+'%';document.getElementById('fp').textContent=row.fp.toLocaleString();document.getElementById('fn').textContent=row.fn.toLocaleString();}
